/* Inspect dimensions and orbit the actual catalogue geometry before insertion. */
const StudioPartPreview=(()=>{
 async function open(part,onInsert){await window.Studio3DAssets.ready();const T=window.THREE,draft=structuredClone(part);let object,renderer,controls,raf,disposed=false;
  const labels={width:'Width',height:'Height',depth:'Depth',length:'Length',thickness:'Thickness',diameter:'Diameter',outerDiameter:'Outer diameter',innerDiameter:'Inner diameter',boreDiameter:'Bore diameter',wallThickness:'Wall thickness',teeth:'Teeth count'};
  modal('Preview & customize · '+part.name,`<p>${esc(part.desc)}. Orbit the preview, change dimensions, then add the part when it looks right. Dimensions are millimetres.</p><div class="partPreviewGrid"><div id="partPreviewCanvas"></div><section>${Object.entries(draft.dims).map(([key,value])=>`<label>${esc(labels[key]||key)}<input type="number" step="${key==='teeth'?1:.1}" id="preview_${key}" value="${value}" min="${key==='teeth'?6:.1}" max="${key==='teeth'?120:5000}"></label>`).join('')}<label>Material<select id="previewMaterial">${StudioAssembly.materials.map(m=>`<option ${m===draft.mat?'selected':''}>${esc(m)}</option>`).join('')}</select></label><button type="button" id="updatePartPreview">Update preview</button><p id="partPreviewError" role="alert"></p></section></div><p class="tiny">These are editable concept parts. Real threads, vendor dimensions and physical fit need verification.</p>`,()=>false);
  const dialog=document.getElementById('dialog');dialog.classList.add('toolsDialog','partPreviewDialog');document.querySelector('#modalForm>button[type=submit]').textContent='Add customized part';
  const scene=new T.Scene(),camera=new T.PerspectiveCamera(40,1,.01,10000);scene.background=new T.Color(0x17271f);scene.add(new T.HemisphereLight(0xffffff,0x536b58,2));const light=new T.DirectionalLight(0xffffff,3);light.position.set(8,12,10);scene.add(light);
  const dispose=o=>o?.traverse(c=>{c.geometry?.dispose();if(c.material)(Array.isArray(c.material)?c.material:[c.material]).forEach(m=>m.dispose());});
  function rebuild(){try{const dims=Object.fromEntries(Object.keys(draft.dims).map(k=>[k,Number(document.getElementById('preview_'+k).value)]));if(!StudioAssembly.dimensions(part.id,dims))throw Error('Check dimensions: bores and walls must fit, and teeth must be whole numbers.');const next={...draft,dims,mat:document.getElementById('previewMaterial').value};const mesh=window.Studio3DAssets.build({partId:part.id,dims:next.dims,material:next.mat});if(object){scene.remove(object);dispose(object);}object=mesh;scene.add(object);draft.dims=dims;draft.mat=next.mat;const box=new T.Box3().setFromObject(object),centre=box.getCenter(new T.Vector3()),distance=Math.max(1,box.getSize(new T.Vector3()).length()*1.6);controls?.target.copy(centre);camera.position.copy(centre).add(new T.Vector3(.7,.65,1).normalize().multiplyScalar(distance));controls?.update();document.getElementById('partPreviewError').textContent='';return true;}catch(e){document.getElementById('partPreviewError').textContent=e.message;return false;}}
  try{renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.domElement.setAttribute('aria-label','3D preview of '+part.name);renderer.domElement.tabIndex=0;document.getElementById('partPreviewCanvas').appendChild(renderer.domElement);controls=new T.OrbitControls(camera,renderer.domElement);}catch(e){document.getElementById('partPreviewError').textContent='3D preview unavailable: '+e.message;}
  document.getElementById('updatePartPreview').onclick=rebuild;for(const key of Object.keys(draft.dims))document.getElementById('preview_'+key).onchange=rebuild;document.getElementById('previewMaterial').onchange=rebuild;
  document.getElementById('modalForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');if(button.disabled||!rebuild())return;button.disabled=true;try{await onInsert(structuredClone(draft));dialog.close();}catch(e){document.getElementById('partPreviewError').textContent=e.message;}finally{button.disabled=false;}};
  function animate(){if(disposed||!renderer)return;const host=document.getElementById('partPreviewCanvas');if(!host)return;const w=Math.max(1,host.clientWidth),h=Math.max(1,host.clientHeight);if(renderer.domElement.width!==Math.round(w*renderer.getPixelRatio())||renderer.domElement.height!==Math.round(h*renderer.getPixelRatio())){renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}controls.update();renderer.render(scene,camera);raf=requestAnimationFrame(animate);}
  dialog.addEventListener('close',()=>{disposed=true;cancelAnimationFrame(raf);controls?.dispose();renderer?.dispose();dispose(scene);dialog.classList.remove('toolsDialog','partPreviewDialog');},{once:true});rebuild();animate();
 }
 return {open};
})();
